import{_ as o,a0 as p,w as r,s as l,ao as d,I as n,x as a,a1 as i,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"Linux 上搭建 Minecraft 服務器 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 上搭建 Minecraft 服務器 | LCTT (201701) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 上搭建 Minecraft 服務器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 上搭建 Minecraft 服務器 | LCTT (201701) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201701/20161225 Minecraft Server on Linux","title":"Linux 上搭建 Minecraft 服務器","tag":"201701","desc":""},"relativePath":"201701/20161225 Minecraft Server on Linux.md","filePath":"[post].md"}'),c={name:"201701/20161225 Minecraft Server on Linux.md"};function h(u,e,g,f,m,b){const s=p("Link");return r(),l("div",null,[e[13]||(e[13]=d(`<h1 id="linux-上搭建-minecraft-服務器" tabindex="-1">Linux 上搭建 Minecraft 服務器 <a class="header-anchor" href="#linux-上搭建-minecraft-服務器" aria-label="Permalink to “Linux 上搭建 Minecraft 服務器”">​</a></h1><p><img src="https://www.linuxforum.com/attachments/title-jpg.89/" alt="Title.jpg"></p><p>“我的世界（Minecraft）”是一個人們可以在各種遊戲主機和計算機上玩的主流遊戲。 截止至 2016 年 6 月，在各種平台上已經售出了超過十億六千萬份。因其受歡迎，你可能想在家裏舉辦一個“我的世界”派對，那麼你就需要安裝一個 “我的世界” 服務器，讓所有的玩家連接到同一個世界中一起玩。</p><h3 id="系統要求" tabindex="-1">系統要求 <a class="header-anchor" href="#系統要求" aria-label="Permalink to “系統要求”">​</a></h3><p>要開始的話，你需要一個有相當數量內存的 Linux 操作系統。你要在服務器上容納的玩家越多，你就需要越多的內存。硬盤空間倒不是需求很大，只要足夠去安裝 Java 以及“我的世界”服務器 Java 文件就行。Minecraft 服務器需要有一個穩定的網絡連接，不管是有線還是無線網絡。</p><p>讓我們看看 “我的世界”服務器最低要求：</p><ul><li><strong>CPU：</strong>雙核或更好。</li><li><strong>內存：</strong> 2 GB （20-40 用户量)，3 GB（30-60 用户量），8 GB（60+ 用户量）。</li><li><strong>系統：</strong> 不需要圖形化用户接口，可以留出更多的空閒資源。</li></ul><p><strong>備註：</strong> 這是“我的世界” 服務端程序的需求，而不是一個完整的操作系統的需求。如果可以給我的世界服務器分配更多的資源，它將運行得更好。</p><p>###安裝 Java</p><p>如果你用 Linux 操作系統運行它的話，你需要安裝最新版本的 Java 環境。</p><p>為了驗證你的 Java 版本，位於終端輸入以下命令：<code>java -version</code>。結果應該是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>java version &quot;1.8.0_101&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Java(TM) SE Runtime Environment (build 1.8.0_101-b13)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Java HotSpot(TM) Client VM (build 25.101-b13, mixed mode)</span></span></code></pre></div><p>如果你當前的 Java 版本不是 1.8 或者更高，則通過在 Ubuntu 系統的終端下執行以下操作來安裝 Java 版本 8：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo add-apt-repository ppa:webupd8team/java</span></span>
<span class="line"><span>sudo apt-get update</span></span>
<span class="line"><span>sudo apt-get install oracle-java8-installer</span></span></code></pre></div><p><strong>注意：</strong>如果 <code>add-apt-repository</code> 命令無法找到，運行 <code>sudo apt-get install software-properties-common</code> 來安裝。 您還可以將第三個命令中更改為 <code>oracle-java9-installer</code> 來安裝最新的 java 版本。</p><p>對於 Redhat 系統（如 CentOS），請使用以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo yum install java-1.8.0-openjdk</span></span></code></pre></div><p>安裝後，核實鍵入版本命令 <code>java-version</code> ，並且核實輸出。這樣你就有了一個適當的 Java 版本，你可以繼續進行接下來的安裝。</p><h3 id="我的世界-服務器版本下載" tabindex="-1">“我的世界”服務器版本下載 <a class="header-anchor" href="#我的世界-服務器版本下載" aria-label="Permalink to ““我的世界”服務器版本下載”">​</a></h3><p>接下來做的事就是去檢查用户將運行的“我的世界”的版本。圖 1 顯示了一個正在運行的 ”我的世界“ ，注意左下角的版本號。</p><p><img src="https://www.linuxforum.com/attachments/figure-01-jpg.85/" alt="Figure 01.jpg"></p><p><em>圖 1</em></p><p>請記住“我的世界”客户端版本號。每個客户端應該是相同的版本才行。</p><p>您接下來要做的是下載客户端所需要的“我的世界”的服務器版本。為了下載該版本你需要知道它的位置。得到所需的文件的命令是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo wget https://s3.amazonaws.com/Minecraft.Download/versions/[version]/minecraft_server.[version].jar</span></span></code></pre></div><p>在 圖1 看到，版本號是 1.10.2。那麼這個命令就該變成：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo wget https://s3.amazonaws.com/Minecraft.Download/versions/1.10.2/minecraft_server.1.10.2.jar</span></span></code></pre></div><p>當你下載好文件，會保存到你當前目錄下。使用命令 <code>pwd</code> 確定當前位置。</p><p>一旦你有了該文件，知道它所保存的文件夾就可以繼續了。</p><h3 id="服務器信息" tabindex="-1">服務器信息 <a class="header-anchor" href="#服務器信息" aria-label="Permalink to “服務器信息”">​</a></h3><p>在啓動“我的世界”服務器之前，您必須知道當前系統上能被你使用的可用內存大小。 當啓動“我的世界”服務器時，你將需要指定起始內存量和當更多玩家加入時最大分配的內存量。 再次提示，重要的是要有足夠的內存。 如果可以，使用最小化安裝操作系統來留出更多的內存，例如最小化安裝的 Ubuntu。</p><p>一旦你有了所需的“我的世界”服務器文件，就可以確定分配給“我的世界”的內存數量。 要確定可用內存，打開一個終端並鍵入以下命令 ，示例輸出如圖 2 所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>free -h</span></span></code></pre></div><p><img src="https://camo.githubusercontent.com/686cb2c9421f276e1cab0b08b713f636ed3ca614/68747470733a2f2f7777772e6c696e7578666f72756d2e636f6d2f6174746163686d656e74732f6669677572652d30322d6a70672e38362f" alt="Figure 02.jpg"></p><p><em>圖 2</em></p><p>如圖 2 所示，在這個低端系統上你可以看到那只有 684 MB 空閒內存。這不是一個可以用於搭建一個 “我的世界” 服務器的系統。在另一個服務器上我有 2.8 GB 內存可供給“我的世界” 使用。</p><p>在我們啓動服務器之前，我們需要找到服務器的 IP 地址。 為此，請運行命令 <code>ifconfig</code>。 如圖 3 所示，應該列出了網絡連接，顯示 <code>Internet Address</code> 或 <code>inet addr</code>，這裏是 <code>192.168.0.2</code>。 在我的服務器系統上，它列出的地址是 <code>192.168.0.14</code>，這個地址是客户端系統將要使用的地址。</p><p><img src="https://camo.githubusercontent.com/62dc2bfe97f8df7895d606c594d74f27b4881ee4/68747470733a2f2f7777772e6c696e7578666f72756d2e636f6d2f6174746163686d656e74732f6669677572652d30332d6a70672e38372f" alt="Figure 03.jpg"></p><p><em>圖 3</em></p><h3 id="啓動-我的世界-服務器" tabindex="-1">啓動“我的世界”服務器 <a class="header-anchor" href="#啓動-我的世界-服務器" aria-label="Permalink to “啓動“我的世界”服務器”">​</a></h3><p>下一步才是真正的啓動“我的世界”服務器。在我們實際開始前，會涉及到幾個選項。當啓動“我的世界”服務器時，你需要指定用多少內存來初始化“我是世界”。 您還將指定使用的最大內存量。</p><p>如果我的系統有 3.7GB 閒置內存，我知道會有不到 40 位玩家，於是我只需要劃出 2GB。當然，我可以增加些以允許用户增長。如果需要的話，我還可以留一點內存給系統運行。我將最小值設置為 2 GB，最大值設置為 3 GB。 由於最大值設置為 3 GB，如果需要的話，還可以至少留給系統 700 MB 內存，但這隻有在“我的世界”服務器使用超過最初分配的2 GB 時才會發生。</p><p>啓動服務器的命令列是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo java -Xms# -Xmx# -jar [path]/minecraft_server.[version].jar nogui</span></span></code></pre></div><p>現在解釋一下命令結構：</p><ul><li>-Xms# - 初始啓動分配的內存（<code>-Xms2048m</code>）</li><li>-Xmx# - 最大分配的內存（<code>-Xmx3096m</code>）</li><li>[path] – “我的世界” 服務器文件路徑（ <code>/home/tux/MCS/</code>）</li><li>[version] – 下載的“我的世界” 服務器的版本（<code>1.10.2</code>）</li><li>nogui – 用於以基於文本的界面來顯示，可以減少內存使用。如果你使用圖形化界面，那麼移除 <code>nogui</code> 選項。</li></ul><p>一個使用 2GB 內存以及最大 3GB、位置為 <code>/home/tux/MCS</code>、 版本號為 <code>1.10.2</code> 的系統的完整命令實例是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo java -Xms2048m -Xmx3096m -jar /home/tux/MCS/minecraft_server.1.10.2.jar nogui</span></span></code></pre></div><p><strong>注意：</strong> 這裏內存容量的大小是兆字節單位。容量要乘以 1024。舉個例子，2GB 的內存使 2 與 1024 相乘，容量為 2048。但別忘小寫字母 <code>m</code> 是特指兆字節。你可以簡單地使用特指的 <code>2g</code> 和 <code>3g</code> 來表示 2GB 和 3GB。</p><p>在你首次運行服務器時會發成一些錯誤。開始之前，它表明需要同意 “最終用户許可協議 EULA”。</p><p>要同意 “最終用户許可協議 EULA”，你需要編輯與“我的世界”服務器 JAR 文件同一文件夾下的的 <code>eula.txt</code> 文件。</p><p>使用一個類似 <code>nano</code> 的文件編輯器打開文件 <code>eula.txt</code> 文件。確定你進行這步時使用的是 root 權限。將行 <code>eula = false</code> 更改為 <code>eula = true</code>，並保存文件。</p><p>現在，再次輸入上述命令以啓動服務器。 應該滾過滿屏幕信息，然後一個狀態行將顯示它的創建過程。 當其這個初始世界創建好之後，狀態行將顯示 100％。 有關係統時間更改的任何錯誤消息是正常的，因此忽略它們。</p><p>此時，你可以打開客户端程序並且看到如上圖 1 的界面。點擊“Multiplayer”按鈕。在下一屏幕，如圖 4，選擇 “Direct Connect”，這將提示您輸入服務器地址，因此鍵入“我的世界”服務器的 IP 地址。你現在應該已經連接到遊戲了。</p><p><img src="https://camo.githubusercontent.com/6893151530092ac59b7b04d17ca5bc07d9bfc9b4/68747470733a2f2f7777772e6c696e7578666f72756d2e636f6d2f6174746163686d656e74732f6669677572652d30342d6a70672e38382f" alt="Figure 04.jpg"></p><p><em>圖 4</em></p><h3 id="連接的某些麻煩" tabindex="-1">連接的某些麻煩 <a class="header-anchor" href="#連接的某些麻煩" aria-label="Permalink to “連接的某些麻煩”">​</a></h3><p>如果一些客户端無法連接到服務器，那麼你需要按下 <code>CTRL+Z</code> 退出 Java 程序。打開文件 <code>server.propertices</code>， 使用一個 nano 之類的編輯器進行編輯。記住要 root 權限。編輯 <code>online-mode</code> 行，它應該設置為 <code>true</code> ，修改為 <code>false</code> 並保存。重啓服務器並打開“我的世界”服務器。使用客户端重新連接到服務器，現在應該一切都好了。</p><p>建設快樂！</p><hr>`,60)),n("p",null,[e[1]||(e[1]=a("via: ",-1)),i(s,{href:"https://www.linuxforum.com/threads/minecraft-server-on-linux.3202/"},{default:t(()=>[...e[0]||(e[0]=[a("https://www.linuxforum.com/threads/minecraft-server-on-linux.3202/",-1)])]),_:1})]),n("p",null,[e[5]||(e[5]=a("作者：",-1)),i(s,{href:"https://www.linuxforum.com/members/jarret.268/"},{default:t(()=>[...e[2]||(e[2]=[a("Jarret",-1)])]),_:1}),e[6]||(e[6]=a(" 譯者：",-1)),i(s,{href:"http://www.itxdm.me"},{default:t(()=>[...e[3]||(e[3]=[a("erlinux",-1)])]),_:1}),e[7]||(e[7]=a(" 校對：",-1)),i(s,{href:"https://github.com/wxy"},{default:t(()=>[...e[4]||(e[4]=[a("wxy",-1)])]),_:1})]),n("p",null,[e[10]||(e[10]=a("本文由 ",-1)),i(s,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...e[8]||(e[8]=[a("LCTT",-1)])]),_:1}),e[11]||(e[11]=a(" 原創編譯，",-1)),i(s,{href:"https://linux.cn/"},{default:t(()=>[...e[9]||(e[9]=[a("Linux中國",-1)])]),_:1}),e[12]||(e[12]=a(" 榮譽推出",-1))])])}const C=o(c,[["render",h]]);export{x as __pageData,C as default};
